from typing import List

class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        if sum(nums) < target:
            return -1

        ops = 0
        sorted_nums = sorted(nums)

        while True:
            total = 0
            last_skipped = -1

            for i in range(len(sorted_nums) - 1, -1, -1):
                if total + sorted_nums[i] > target:
                    last_skipped = i
                    continue

                total += sorted_nums[i]

                if total == target:
                    return ops

            if last_skipped == -1:
                return -1

            new = sorted_nums.pop(last_skipped) // 2
            sorted_nums.append(new)
            sorted_nums.append(new)
            ops += 1

